#[test]
fun test_reserve_flash_loan_works() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);

    let ctx = scenario_value.ctx();
    let mut reserve = new<MainMarket, BTC>(ctx, 1);

    let amount = 1000;
    let btc = sui::balance::create_for_testing<BTC>(amount).into_coin(ctx);
    let ctokens = reserve.mint_ctokens<MainMarket, BTC>(btc).into_coin(ctx);
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    let (borrowed_balance, loan) = reserve.borrow_flash_loan<MainMarket, BTC>(100);

    assert!(borrowed_balance.value() == 100);
    assert!(reserve.cash == 1000);
    assert!(reserve.debt.is_zero());
    assert!(reserve.cash_reserve.is_zero());
    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));
    assert!(reserve.util_rate().is_zero());

    assert!(loan.amount() == 100);

    let repay_btc = sui::balance::create_for_testing<BTC>(100).into_coin(ctx);
    let fee_btc = sui::balance::create_for_testing<BTC>(1).into_coin(ctx);
    reserve.repay_flash_loan(loan, repay_btc, fee_btc);
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    assert!(reserve.cash == 1001);
    assert!(reserve.debt.is_zero());
    assert!(reserve.cash_reserve.eq(float::from(1)));
    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));
    assert!(reserve.util_rate() == float::from_quotient(0, 1));

    std::unit_test::destroy(ctokens);
    std::unit_test::destroy(borrowed_balance);
    std::unit_test::destroy(reserve);
    scenario_value.end();
}

/// @title A module dedicated for handling the borrow request from user
module protocol::borrow;

use std::type_name::{Self, TypeName};
use sui::clock::{Self, Clock};
use sui::coin::{Self, Coin};
use sui::event::emit;

use math::float::Decimal;

use x_oracle::x_oracle::XOracle;

use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;
use protocol::liquidity_miner::get_borrow_reward_type;
use protocol::app::ProtocolApp;

public struct BorrowEvent has copy, drop {
    borrower: address,

    market: TypeName,
    obligation: ID,

    asset: TypeName,

    amount: u64,
    total_borrow: Decimal,
    borrow_index: Decimal,

    time: u64,
}

public fun borrow<MarketType, CoinType>(
    app: &ProtocolApp,
    obligation_owner_cap: &ObligationOwnerCap,
    market: &mut Market<MarketType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    borrow_amount: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): Coin<CoinType> {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let now = clock::timestamp_ms(clock) / 1000;

    let (borrowed_balance, borrow_index, total_borrow) = market.handle_borrow(
        obligation_owner_cap.id(),
        borrow_amount,
        coin_decimals_registry,
        x_oracle,
        clock,
        now
    );

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, CoinType>(
        get_borrow_reward_type(),
        obligation_owner_cap.id(),
        total_borrow.floor(),
        clock
    );

    // Emit the borrow event
    emit(BorrowEvent {
        borrower: ctx.sender(),

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),

        asset: type_name::with_defining_ids<CoinType>(),
        amount: borrow_amount,

        total_borrow,
        borrow_index,

        time: now,
    });

    coin::from_balance(borrowed_balance, ctx)
}

